def dist(a,b,c,d):
    p1,p2=math.radians(a),math.radians(c);h=math.sin((p2-p1)/2)**2+math.cos(p1)*math.cos(p2)*math.sin(math.radians(d-b)/2)**2
    return round(2*6371000*math.asin(math.sqrt(h)))
out=[];moves=[]
for i,s in enumerate(src):
    r=R[i]
    lat=r.get('lat',s['lat']);lng=r.get('lng',s['lng'])
    d=dist(s['lat'],s['lng'],lat,lng)
    note=r['n']
    if r['v']!='correct' and d>0: note=(note+"; " if note else "")+f"moved {d} m from old pin"
    out.append({"id":s['id'],"title":s['title'],"verdict":r['v'],"lat":lat,"lng":lng,"precision":r['p'],"address":r['a'],"evidence_url":r['u'],"evidence":r['e'],"notes":note})
    if d>0: moves.append((d,s['id'],s['title'],r['v']))
json.dump(out,open('/Users/ksh/agents/news-agent/armenia-new-builds/scraper/geo_verified_1.json','w'),ensure_ascii=False,indent=1)
from collections import Counter
print(Counter(o['verdict'] for o in out))
